#!/bin/sh
umask 077
gun=${1:-$(date +%Y%m%d)}
in=/data/giden/stok_${gun}.txt
[ -f "$in" ] || { echo "girdi yok: $in" >&2; exit 3; }
n=$(wc -l < "$in"); t=$(awk -F, '{s+=$2} END {print s}' "$in")
echo "KALEM=$n TOPLAM=$t" > /data/arsiv/stok_kapanis_${gun}.txt
echo "kapanis dosyasi yazildi: KALEM=$n TOPLAM=$t"
